using System.Text;
internal static class LibraryQuantitySemanticsTests{
 internal static async Task Run(){
  var temp=Path.Combine(Path.GetTempPath(),"LibraryUnitBasis-"+Guid.NewGuid().ToString("N"));var h=new SimAssemblyHeader("01PART                ","fixture","V1.2","PART                ","PART","A","202020","A",false);var store=new SimLibraryBomStore(temp,()=>[h]);var key=h.SourceKeyRaw;var actor=new SimPersona("editor","editor","Fixture","ACTIVE",[],["assembly_library.view","assembly_library.edit"],false,"fixture");
  void Check(bool b,string label){if(!b)throw new Exception(label);}async Task Reject(Func<Task> f,string label){try{await f();}catch(SimRfqIntakeProblem){return;}throw new Exception("Expected rejection: "+label);}
  string Txt(string divisor="1")=>string.Join('\t',SimVproParser.Headers)+"\tDRAW#=PART REV A\n"+string.Join('\t',new[]{"010","A7-129","Capacitor","",divisor,"1","EA","1","0","0","0","P",""})+"\n"+string.Join('\t',new[]{"011","","(2) C5","","0","0","","0","0","0","0","",""})+"\n"+string.Join('\t',new[]{"088","F2-342","Stock header","","1","1","EA","1","0","0","0","P",""})+"\n"+string.Join('\t',new[]{"090","","(18) J2,3,4,5,6 - CUT TO SIZE","","0","0","","0","0","0","0","",""})+"\n";
  var v=await store.Get(key,actor);v=await store.Change(new(key,v.Token,"START"),actor);Check(v.Record.Draft!.QuantityBasis=="PER_ASSEMBLY"&&!v.Record.Draft.PreparationAssessed,"schema default without human attestation");await Reject(async()=>await store.Change(new(key,v.Token,"IMPORT",FileName:"bad.txt",TextBase64:Convert.ToBase64String(Encoding.ASCII.GetBytes(Txt("2")))),actor),"unsupported divisor not converted");
  v=await store.Change(new(key,v.Token,"IMPORT",FileName:"bom.txt",TextBase64:Convert.ToBase64String(Encoding.ASCII.GetBytes(Txt()))),actor);Check(v.PreparationRowIds!.Length==0&&v.SourceInstructionRowIds!.SequenceEqual(new[]{"vpro-088"}),"source cutting note advisory, ordinary rows unaffected");var rows=v.Record.Draft!.Rows.Select(r=>new LibraryRowEdit(r.Id,r.Find,r.SourcePartNumber,r.Description,r.Quantity,r.Unit,r.ReferenceDesignators,"CUSTOMER","","",true,false,"",false)).ToArray();
  var q=v.Record.Draft.Rows.Select(r=>(r.Quantity,r.Unit)).ToArray();var cmd=new LibraryBomCommand(key,v.Token,"ACCEPT_ROW",DrawingRevision:"A",BomRevision:"A",QuantityBasis:"",PreparationAssessed:false,Rows:rows,RowId:"vpro-010");v=await store.Change(cmd,actor);Check(v.Record.Draft!.Rows[0].Acceptance is not null&&!v.Record.Draft.PreparationAssessed,"ordinary row accepted without blanket prep confirmation");Check(v.Record.Draft.Rows.Select(r=>(r.Quantity,r.Unit)).SequenceEqual(q),"no quantity/unit change");Check(v.Record.Draft.Rows[1].Acceptance is null,"no automatic preparation row acceptance");v=await store.Change(cmd with{ExpectedToken=v.Token,RowId="vpro-088"},actor);Check(v.Record.Draft!.Rows[1].Acceptance is not null,"purchased stock row accepted without production attestation");await Reject(async()=>await store.Change(cmd with{ExpectedToken=v.Token,QuantityBasis="PER_BATCH"},actor),"explicit incompatible basis rejected");Check(!SimLibraryBomStore.Blockers(v.Record.Draft).Any(x=>x.Contains("Preparation details pending")),"source note alone does not block BOM review");
  var legacy=v.Record.Draft with{QuantityBasis="",PreparationAssessed=false,RowAcceptanceRequired=false,Import=null,Rows=[v.Record.Draft.Rows[0] with{Acceptance=null}]};Check(!SimLibraryBomStore.Blockers(legacy).Any(x=>x.Contains("quantities are")||x.Contains("Review preparation")),"legacy blank uses schema basis");Check(SimLibraryBomStore.Blockers(legacy with{QuantityBasis="PER_BATCH"}).Any(x=>x.Contains("basis")),"legacy explicit incompatible reported");var decimalRow=legacy.Rows[0] with{Find="18.1",Source=new("vpro-010",new(){["lineNumber"]="18.1"},null,[])};Check(!SimLibraryBomStore.PreparationApplies(legacy,decimalRow),"decimal find alone not preparation");Check(SimLibraryBomStore.PreparationApplies(legacy,decimalRow with{PreparationRequired=true}),"explicit preparation retained");Check((await new SimLibraryBomStore(temp,()=>[h]).Get(key,actor)).Record.Draft!.Rows[0].Acceptance is not null,"save/reopen");
  Console.WriteLine("PASS per-one-assembly schema/default and legacy blank, ordinary Find2 acceptance without global checks, no numeric conversion, incompatible basis/divisor rejection, advisory Find18 cut-note and explicit flag retained, no decimal inference, downstream preparation block, save/reopen.");
 }
}
